function pageBounds(){return slideBounds(slide());}
function layoutItems(){return occupiedItems(slide());}
function moduleName(m){return m.type==='table'?(m.sectionedTable?m.parts[tablePartIndex(m)]?.title||'':m.tableTitle||''):m.groupTitle||(m.parts.length===1?m.parts[0].title:'');}
function syncTextDelete(){const el=$('#delete-edit-scope');if(!el)return;const m=slide().modules.find(m=>m.id===editingTarget?.moduleId);el.disabled=!m||editingTarget?.slideId!==slide().id||(textBlocks?.batch().length||0)>1;el.querySelector('option[value="part"]').disabled=!m||editingTarget?.part===null||m.parts.length<=1;}
function childControls(m){return '<div class="timeline-stage-controls">'+m.parts.map((p,i)=>'<div class="field-line"><span class="stage-label" title="'+esc(p.title||p.caption||'子区域')+'">'+(i+1)+' · '+esc(p.title||p.caption||'子区域')+'</span><button data-child-move="'+i+'" data-direction="-1" '+(i===0?'disabled':'')+' title="子区域上移" aria-label="子区域上移">↑</button><button data-child-move="'+i+'" data-direction="1" '+(i===m.parts.length-1?'disabled':'')+' title="子区域下移" aria-label="子区域下移">↓</button><button data-child-remove="'+i+'" '+(m.parts.length<=1?'disabled':'')+'>删除</button></div>').join('')+'</div>';}
function childIndex(m){return Math.min(childFocus.get(m.id)??(m.parts.length-1),m.parts.length-1);}
function tablePartIndex(m){return Math.min(tableFocus.get(m.id)||0,m.parts.length-1);}
function currentTable(m=selectedModule()){return tableOwner(m,tablePartIndex(m));}
function planPageChange(id,rect,step=project.grid){const items=layoutItems(),plan=planChange(items,id,rect,step,pageBounds());if(!plan)return null;for(const fixed of items.filter(m=>m.fixed)){const r=plan.find(m=>m.id===fixed.id);if(['x','y','w','h'].some(k=>r[k]!==fixed[k]))return null;}return plan.filter(m=>!m.fixed);}
function moduleList(){return '<h3>本页模块</h3><div class="module-card-list">'+slide().modules.map(m=>'<button data-select-module="'+m.id+'">'+esc(m.groupTitle||m.tableTitle||m.parts[0]?.title||({text:'文字',table:'表格',media:'图像／视频'}[m.type]||m.type))+'<small>'+esc(m.sectionedTable?m.parts.length+' 个表格子区域':m.type==='table'?(m.profileHistory?'履历横线表':'数据表'):m.parts.length+' 个子区域')+'</small></button>').join('')+'</div>';}
function chooseSpace(type,callback){
 if(slide().kind!=='body'||slide().referenceLayout){toast('请在可模块编辑的正文页插入。',true);return;}
 spaceChoices=findSpaces(layoutItems(),project.grid,pageBounds(),type.startsWith('textbox')?{type:'text',textBox:true}:{});
 spaceChoices=spaceChoices.filter(r=>r.w>=200&&r.h>=(type==='media'?120:type==='table'?140:type.startsWith('textbox')?80:180));
 if(!spaceChoices.length){toast('当前没有足以容纳此模块的空白区域，请缩小已有模块或新增一页。',true);return;}
 if(spaceChoices.length===1){callback(spaceChoices[0]);return;}spaceCallback=callback;
 newDialog('space-dialog','选择插入区域','<p class="hint">检测到多个互不相连的空白区域，请选择一处。灰色是已有内容，蓝色是本次插入位置；插入后可继续按网格移动和调整。</p><div class="space-choice-grid">'+spaceChoices.map((r,i)=>'<button type="button" class="space-choice" data-free-area="'+i+'"><svg viewBox="0 0 1600 900"><rect width="1600" height="900" fill="white"/>'+layoutItems().map(m=>'<rect x="'+m.x+'" y="'+m.y+'" width="'+m.w+'" height="'+m.h+'" fill="#dbe3e9"/>').join('')+'<rect x="'+r.x+'" y="'+r.y+'" width="'+r.w+'" height="'+r.h+'" fill="#005b94" fill-opacity=".25" stroke="#005b94" stroke-width="6"/></svg><strong>区域 '+(i+1)+'</strong><small>'+Math.round(r.w)+' × '+Math.round(r.h)+' px · 点击插入</small></button>').join('')+'</div>','选择区域');document.querySelector('[data-action="space-dialog-apply"]').hidden=true;
}
function outlineDialog(){openOutlineImport({getProject:()=>project,toast,applyProject:(next,{newDocument=false}={})=>{savePoint();project=next;if(newDocument)htmlFileHandle=null;index=0;selected=null;mode='text';render();pageList.reset();persist();}});}
function quickInsert(type){chooseSpace(type,rect=>{const box=type.startsWith('textbox'),m=moduleOf(box?'text':type,rect,1);if(box){m.textBox=true;m.boxTone=type==='textbox-light'?'light':'dark';m.parts[0].title='';m.parts[0].text='输入正文';}if(type==='text'){m.style='cards';m.parts[0].title='新文本块';m.parts[0].text='在此输入正文。';}if(type==='table')m.rows=[['项目','指标'],['名称','数值'],['名称','数值']];if(type==='media'&&rect.h<200)m.parts[0].showCaption=false;savePoint();slide().modules.push(m);selected=m.id;mode='edit';render();persist();});}

function adjustModule(kind,operation,count=1,record=true){
 const m=selectedModule();if(!m||present)return false;
 const anchor=$('#resize-anchor')?.value||'tl',d=project.grid;let applied=false;
 for(let n=0;n<count;n++){
  const current=selectedModule();let rect;
  if(kind==='resize'){
   const [dx,dy]={'w+':[d,0],'w-':[-d,0],'h+':[0,d],'h-':[0,-d]}[operation];
   rect=anchoredResize(current,dx,dy,anchor);
   if((dx<0||dy<0)&&!testFit(current,rect))break;
  }else rect={x:current.x+(operation==='right'?d:operation==='left'?-d:0),y:current.y+(operation==='down'?d:operation==='up'?-d:0),w:current.w,h:current.h};
  const plan=planPageChange(current.id,rect,d);if(!plan)break;
  if(!applied&&record)savePoint();slide().modules=plan;applied=true;
 }
 if(applied){render();persist();}return applied;
}
function startAdjust(e){
 const b=e.target.closest('button[data-resize],button[data-move]');if(!b||b.disabled||e.button!==0)return;
 stopAdjust();holdUsed=false;const kind=b.dataset.resize?'resize':'move',operation=b.dataset.resize||b.dataset.move,count=e.shiftKey?5:adjustMultiplier;
 holdTimer=setTimeout(()=>{holdUsed=true;let recorded=false;const tick=()=>{const ok=adjustModule(kind,operation,count,!recorded);if(ok)recorded=true;else clearInterval(holdInterval);};tick();holdInterval=setInterval(tick,85);},320);
}
function stopAdjust(){clearTimeout(holdTimer);clearInterval(holdInterval);if(holdUsed){holdSuppressUntil=Date.now()+250;holdUsed=false;}}
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const slide=()=>project.slides[index];
const selectedModule=()=>slide().modules.find(m=>m.id===selected);
const hex=/^#[\da-f]{6}$/i;
function updateTextElement(el,lineSpacing=null,colorChoice=null,options={}){
 const moduleEl=el.closest('[data-module]'),m=moduleEl?slide().modules.find(n=>n.id===moduleEl.dataset.module):null;
 let owner,key,cell;
 if(el.dataset.slideField){owner=slide();key=el.dataset.slideField;}
 else if(el.dataset.row!==undefined){owner=el.dataset.tablePart!==undefined?m.parts[Number(el.dataset.tablePart)]:m;cell=el.dataset.row+','+el.dataset.col;key='cell';}
 else if(el.dataset.moduleField){owner=m;key=el.dataset.moduleField;}
 else if(m){owner=m.parts[Number(el.dataset.part)];key=el.dataset.field;}
 if(!owner||!key)return;
 const value=readRich(el);
 if(colorChoice){const theme=project.theme,base=getComputedStyle(el).color.match(/\d+/g),original=base?'#'+base.slice(0,3).map(n=>Number(n).toString(16).padStart(2,'0')).join(''):'',target=colorChoice==='theme'?theme.primary:colorChoice==='emphasis'?theme.emphasis:colorChoice==='original'?original:colorChoice;for(const run of value.runs){if(run.color?.toLowerCase()!==target?.toLowerCase())continue;if(colorChoice==='original')delete run.color;else if(['theme','emphasis'].includes(colorChoice))run.color=colorChoice;}}
 if(cell){owner.rows[Number(el.dataset.row)][Number(el.dataset.col)]=value.text;owner.cellRich??={};owner.cellRich[cell]=value.runs;owner.cellParagraphs??={};owner.cellParagraphs[cell]=value.paragraphs;if(lineSpacing!==null){owner.cellLineSpacing??={};owner.cellLineSpacing[cell]=lineSpacing;}}
 else{owner[key]=value.text;owner.rich??={};owner.rich[key]=value.runs;owner.paragraphs??={};owner.paragraphs[key]=value.paragraphs;if(lineSpacing!==null){owner.lineSpacing??={};owner.lineSpacing[key]=lineSpacing;}}
 if(options.fontSize){if(cell){owner.cellFontSizes??={};owner.cellFontSizes[cell]=options.fontSize;}else{owner.fontSizes??={};owner.fontSizes[key]=options.fontSize;}}
 if(options.bullet!==undefined){owner.bullet=options.bullet;owner.marker=options.marker;}
 if(m?.isToc&&owner.tocCustomId){const i=slide().tocExtras?.findIndex(p=>p.tocCustomId===owner.tocCustomId);if(i>=0)slide().tocExtras[i]=clone(owner);}
 if(m?.isToc&&owner.chapterId&&key==='text'){slide().tocNotes??={};slide().tocNotes[owner.chapterId]=value.text;slide().tocRich??={};slide().tocRich[owner.chapterId]={rich:owner.rich,lineSpacing:owner.lineSpacing,paragraphs:owner.paragraphs};}
 if(slide().kind==='transition'&&key==='title'){syncSections(project);refreshDerivedPages();}
 if(m)autoGrow(m);freeText?.sync();persist();check();clearTimeout(window.thumbTimer);window.thumbTimer=setTimeout(updateSidebar,500);
}
function removeTocEntry(i){const p=selectedModule().parts[i];if(p.chapterId){slide().tocExcluded??=[];if(!slide().tocExcluded.includes(p.chapterId))slide().tocExcluded.push(p.chapterId);}else slide().tocExtras=(slide().tocExtras||[]).filter(n=>n.tocCustomId!==p.tocCustomId);}
function tocAddDialog(){const hidden=documentSections(project,{includeAppendix:!!slide().tocIncludeAppendix}).filter(ch=>slide().tocExcluded?.includes(ch.id));newDialog('toc-add-dialog','添加目录子区域',`<label>选择目录条目<select id="toc-add-choice">${hidden.map(ch=>`<option value="${ch.id}">恢复：${esc(ch.number+' '+ch.title)}</option>`).join('')}<option value="custom">自定义目录条目</option></select></label><p class="hint">删除自动目录条目不会删除实际章节；恢复后标题与页码继续自动更新。自定义条目可直接编辑标题与说明。</p>`);}
function toast(t,error=false){const el=$('#toast');el.textContent=t;el.classList.toggle('error',error);clearTimeout(timer);timer=setTimeout(()=>el.textContent='',7000);}
function savePoint(){history.push(clone(project));if(history.length>35)history.shift();future=[];}
function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{const db=await database();const t=db.transaction('projects','readwrite');t.objectStore('projects').put(clone(project),'draft');t.onerror=()=>toast('自动保存失败，请立即保存 HTML。',true);}catch{toast('此环境无法自动保存，请使用“保存 HTML”。',true);}},650);}
function database(){return new Promise((resolve,reject)=>{const r=indexedDB.open('html2ppt-web-slide',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function draft(){try{const db=await database();return await new Promise((resolve,reject)=>{const r=db.transaction('projects').objectStore('projects').get('draft');r.onsuccess=()=>resolve(r.result);r.onerror=reject;});}catch{return null;}}
function download(data,name,type){const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function readData(file){return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}
async function raster(src){const im=new Image();im.src=src;await im.decode();const c=document.createElement('canvas');c.width=Math.min(1600,im.naturalWidth||1200);c.height=Math.round(c.width*im.naturalHeight/im.naturalWidth);c.getContext('2d').drawImage(im,0,0,c.width,c.height);return c.toDataURL('image/png');}
function dialog(id,title,body,action='应用'){return `<dialog id="${id}"><form method="dialog"><div class="dialog-head"><h2>${title}</h2><button value="cancel" aria-label="关闭">×</button></div><div class="dialog-body">${body}</div><div class="dialog-actions"><button value="cancel">取消</button><button type="button" class="primary" data-action="${id}-apply">${action}</button></div></form></dialog>`;}
