 const bottom=document.createElement('div');bottom.className='sidebar-bottom';bottom.innerHTML='<p id="page-selection-info" class="sidebar-selection-info"></p><div class="sidebar-clipboard"><button data-action="copy-pages" title="Ctrl+C 复制页">复制</button><button data-action="paste-pages" title="Ctrl+V 粘贴页">粘贴</button></div>';
