 document.addEventListener('focusin',e=>{if(e.target.isContentEditable||e.target.id==='speaker-notes')savePoint();const el=e.target.closest('[data-text][contenteditable="true"]');if(el&&$('#canvas').contains(el)){const owner=el.closest('[data-module]');selected=owner?.dataset.module||null;editingTarget=owner?{slideId:slide().id,moduleId:owner.dataset.module,part:el.dataset.tablePart!==undefined?Number(el.dataset.tablePart):el.dataset.part!==undefined?Number(el.dataset.part):null}:null;if(editingTarget?.part!==null&&editingTarget?.part!==undefined)childFocus.set(owner.dataset.module,editingTarget.part);freeText.focus(el);syncTextDelete();inspector();}});
