 syncSections(project);for(const frame of $$('#pages-surface [data-view-page]')){const i=Number(frame.dataset.viewPage);if(i===index)continue;const canvas=$('.canvas-frame',frame);canvas.innerHTML=renderSlide(project.slides[i],project.theme,i,project.slides.length,false,project);canvas.querySelectorAll('.module').forEach(fitTable);}viewer.fit();
