function resizeCanvas(){viewer?.fit();}
function initInspectorResizer(){
 const resizer=$('#inspector-resizer');if(!resizer)return;
 const MIN=180,MAX=460;
 const saved=Number(localStorage.getItem('inspector-width')||0);
 if(saved>=MIN&&saved<=MAX)document.documentElement.style.setProperty('--inspector-width',saved+'px');
 let dragging=false,startX=0,startW=0;
 resizer.addEventListener('pointerdown',e=>{
  dragging=true;startX=e.clientX;
  const w=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--inspector-width'))||250;
  startW=w;resizer.classList.add('active');resizer.setPointerCapture(e.pointerId);
  document.body.style.cursor='col-resize';document.body.style.userSelect='none';
 });
 resizer.addEventListener('pointermove',e=>{
  if(!dragging)return;
  const w=Math.max(MIN,Math.min(MAX,startW-(e.clientX-startX)));
  document.documentElement.style.setProperty('--inspector-width',w+'px');
  viewer?.fit();
 });
 const end=e=>{
  if(!dragging)return;dragging=false;
  resizer.classList.remove('active');
  try{resizer.releasePointerCapture(e.pointerId);}catch{}
  document.body.style.cursor='';document.body.style.userSelect='';
  const w=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--inspector-width'))||250;
  localStorage.setItem('inspector-width',w);
 };
 resizer.addEventListener('pointerup',end);resizer.addEventListener('pointercancel',end);
}
function check(){const messages=audit($('.slide',$('#canvas')),slide());
 if(['body','toc'].includes(slide().kind)){
  for(const m of slide().modules)if(!inside(m,pageBounds())||layoutItems().some(n=>m.id!==n.id&&intersects(m,n)))messages.push('模块越界或相互遮挡，调整后再导出。');
 }
 return messages;
}
function go(n,options={}){if(n===index&&!present){viewer.scrollTo(n);return;}viewer.select(Math.max(0,Math.min(project.slides.length-1,n)),options);}
function tableSpacingControls(owner,reference=false){
 const prefix=reference?'reference-':'table-',height=owner[reference?'referenceRowHeightPt':'rowHeightPt']||0,padding=owner[reference?'referenceCellPaddingPt':'cellPaddingPt'];
 return `<h3>单元格高度与留白</h3><label>统一最小行高（pt；0为自动）<input id="${prefix}row-height" type="number" min="0" max="120" step="1" value="${height}"></label><label>上下内边距（pt；留空自动）<input id="${prefix}cell-padding" type="number" min="0" max="18" step="0.5" placeholder="自动" value="${padding??''}"></label><p class="hint">整表统一调整。内容较多的行会自然增高，不会被行高设置裁切；左右半字符间距保持不变。</p>`;
}
function inspector(){inspectorBody();if(mode==='text')formatter?.mountAlignment($('#inspector'));const m=selectedModule();if(m&&['formula','table'].includes(m.type)){const section=document.createElement('section');section.innerHTML='<h3>公式颜色</h3><label><input id="symbol-theme-color" type="checkbox" '+(m.mathUseThemeColor?'checked':'')+'> 使用主题色（取消为纯黑）</label><p class="hint">作用于当前模块所有公式。双击公式或表格中的符号，可单独编辑 LaTeX 与颜色。</p><label>承载卡片样式<select id="formula-card-style">'+[['plain','默认 · 白底'],['unified','A1 · 一体浅底'],['cards','A2 · 分立浅底'],['band','A3 · 深底标题']].map(([v,n])=>'<option value="'+v+'" '+((m.cardStyle||m.style||'plain')===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label>';$('#inspector').prepend(section);}}
function inspectorBody(){
 if(freeText?.inspector($('#inspector')))return;
 const m=selectedModule();
 if(!m){$('#inspector').innerHTML=`<h2>页面与模块</h2><div class="stat">${slide().modules.length} 个模块<br>建议间隙：12 px，可按空间紧凑排版<br>网格步进：${project.grid} px</div><div class="empty">${mode==='text'?'直接点击正文即可修改文字。<br>图片 / 视频占位区域可双击上传。':'点击一个模块，查看尺寸、样式和子区域。'}</div>${slide().referenceLayout&&$('#canvas table')?tableSpacingControls(slide(),true):''}${moduleList()}<h3>当前页设置</h3><button data-action="page-settings">标题、页首句与来源</button><h3>排版原则</h3><p class="hint">文字不会自动缩小字号或行距。内容超出时，模块会尝试增高并推开相邻模块；无法容纳时以粗红框提示。</p><p class="hint">所有插图默认为占位区域；图片与视频保持比例。几何图形可单向伸缩。</p>`;return;}
 const anchor=$('#resize-anchor')?.value||'tl';
 const options=[['w+',project.grid,0,'加宽 →'],['w-',-project.grid,0,'收窄 ←'],['h+',0,project.grid,'增高 ↓'],['h-',0,-project.grid,'降低 ↑']];
 $('#inspector').innerHTML=`<h2>${{text:'文字模块',table:'表格模块',media:'图像 / 视频模块',shape:'图形模块',formula:'公式模块',timeline:'时间轴模块'}[m.type]}</h2><div class="stat">位置 ${Math.round(m.x)}, ${Math.round(m.y)} px<br>尺寸 ${Math.round(m.w)} × ${Math.round(m.h)} px</div>${['text','table'].includes(m.type)&&!m.isToc&&!m.textBox?`<label><input id="module-title-show" type="checkbox" ${m.showTitle!==false?'checked':''}> 显示模块名称</label><label>模块名称（可选）<input id="module-name" value="${esc(moduleName(m))}"></label>`:''}<label>固定锚点</label><select id="resize-anchor">${[['tl','左上角'],['tr','右上角'],['bl','左下角'],['br','右下角'],['center','中心']].map(([v,t])=>`<option value="${v}" ${v===anchor?'selected':''}>${t}</option>`).join('')}</select><h3>按网格调整尺寸</h3><label>单次步进<select id="adjust-multiplier">${[1,2,5].map(n=>`<option value="${n}" ${adjustMultiplier===n?'selected':''}>${n} 格 · ${n*project.grid} px</option>`).join('')}</select></label><div class="size-grid">${options.map(([k,x,y,t])=>`<button data-resize="${k}" ${canResize(m,x,y,anchor)?'':'disabled'}>${t}</button>`).join('')}</div><p class="hint">长按按钮连续调整；Shift＋单击调整 5 格。松开即停，一次长按可整体撤销。灰色表示再调整会越界、遮挡或导致内容溢出。相邻模块可容纳时会自动避让。</p><h3>按网格移动</h3><div class="size-grid">${[['left','← 左'],['right','右 →'],['up','↑ 上'],['down','下 ↓']].map(([k,t])=>`<button data-move="${k}">${t}</button>`).join('')}</div>${m.textBox?`<label>独立文本块配色<select id="text-box-tone"><option value="dark" ${m.boxTone!=='light'?'selected':''}>深底白字</option><option value="light" ${m.boxTone==='light'?'selected':''}>白底深字</option></select></label>`:''}${m.type==='text'&&!m.textBox?`<label>文本块样式</label><select id="module-style">${STYLES.filter(([v])=>!m.isToc||v!=='note').map(([v,n,t])=>`<option value="${v}" ${m.style===v?'selected':''}>${n}　${t}</option>`).join('')}</select>${styleControls(m)}${['unified','cards','band','note'].includes(m.style)?`<label>卡片内边距（pt；留空自动）<input id="card-padding" type="number" min="1" max="24" step="1" placeholder="自动" value="${m.cardPaddingPt??''}"></label><p class="hint">允许紧凑留白，只按实际截断和遮挡提示；不会缩小字号。</p>`:''}<label>列表前导符</label><select id="bullet-marker"><option value="">普通段落</option>${['•','–','▪','▸'].map(c=>`<option value="${c}" ${m.parts[0].bullet&&m.parts[0].marker===c?'selected':''}>${c}　无序段落</option>`).join('')}</select><label>自定义前导符（最多两个字符）</label><input id="bullet-custom" maxlength="2" value="${esc(m.parts[0].bullet?m.parts[0].marker:'')}" placeholder="例如 ✓、○、①">`:''}${['text','media','formula'].includes(m.type)&&!m.textBox?`<h3>子区域</h3>${m.isToc?`<p class="hint">自动章节保持标题和页码同步；可删除目录条目、恢复已隐藏章节或添加自定义条目。</p><label><input id="toc-appendix" type="checkbox" ${slide().tocIncludeAppendix?'checked':''}> 目录包含附录（默认不含）</label>${m.parts.map((p,i)=>`<div class="field-line"><span style="flex:1">${esc(p.title)}</span><button data-toc-remove="${i}" ${m.parts.length<=1?'disabled':''}>删除</button></div>`).join('')}<label><input id="toc-page-ranges" type="checkbox" ${m.showPageRanges!==false?'checked':''}> 右下角显示页码范围</label>`:''}${m.isToc?'':childControls(m)}<label>列数</label><select id="module-columns">${Array.from({length:m.parts.length},(_,i)=>`<option value="${i+1}" ${(m.columns||m.parts.length)===i+1?'selected':''}>${i+1} 列</option>`).join('')}</select><div class="size-grid" style="margin-top:12px"><button data-action="add-part" ${m.parts.length>=12?'disabled':''}>＋ 子区域</button></div>`:''}${m.type==='timeline'?`<label><input id="hide-timeline" type="checkbox" ${m.hideTimeline?'checked':''}> 隐藏时间轴装饰（退化为并列图文卡片）</label><h3>卡片（1–6个）</h3><p class="hint">卡片宽度与统一媒体高度随数量调整。文字模式可改标题和说明；双击照片可换成图片或视频。建议2–5张，内容过多请拆页。</p><div class="timeline-stage-controls">${m.parts.map((p,i)=>`<div class="field-line"><span class="stage-label">${esc(p.year)} ${esc(p.title)}</span><button data-stage-move="${i}" data-direction="-1" ${i===0?'disabled':''} title="前移">↑</button><button data-stage-move="${i}" data-direction="1" ${i===m.parts.length-1?'disabled':''} title="后移">↓</button><button data-stage-remove="${i}" ${m.parts.length===1?'disabled':''}>删除</button></div>`).join('')}</div><button data-action="add-part" ${m.parts.length>=6?'disabled':''}>＋ 添加卡片</button>`:''}${m.type==='table'?tableControls(m,tablePartIndex(m),esc,p=>tableSpacingControls(p)):''}<hr><button data-action="mode-text">完成模块编辑 → 编辑文字</button>`;
}
function testFit(m,rect){
 if(!['text','media','table','timeline'].includes(m.type))return true;
 const container=document.createElement('div');container.className='slide';container.style.cssText=themeCSS(project.theme)+';position:fixed;left:-20000px;top:0;visibility:hidden;';
 container.innerHTML=renderModule({...m,...rect});document.body.append(container);const el=$('.module',container);fitTable(el);const target=m.type==='table'?$('.table-wrap',el):$('.module-content',el);const good=measuredHeight(el,m)<=rect.h+2&&target.scrollHeight<=target.clientHeight+2&&target.scrollWidth<=target.clientWidth+2;container.remove();return good;
}
function canResize(m,dx,dy,anchor){const rect=anchoredResize(m,dx,dy,anchor);return !!planPageChange(m.id,rect)&&(dx>=0&&dy>=0||testFit(m,rect));}
function syncModulePositions(){for(const m of slide().modules){const el=$(`[data-module="${m.id}"]`,$('#canvas'));if(el){el.style.left=m.x+'px';el.style.top=m.y+'px';el.style.width=m.w+'px';el.style.height=m.h+'px';fitTable(el);}}}
function autoGrow(m){if(!m)return;const el=$(`[data-module="${m.id}"]`,$('#canvas'));if(!el)return;fitTable(el);const needed=Math.ceil(measuredHeight(el,m)/project.grid)*project.grid;if(needed>m.h+2){const rect={x:m.x,y:m.y,w:m.w,h:needed};const plan=planPageChange(m.id,rect);if(plan){slide().modules=plan;syncModulePositions();}else{for(let h=Math.floor((pageBounds().y+pageBounds().h-m.y)/project.grid)*project.grid;h>m.h;h-=project.grid){const p=planPageChange(m.id,{...rect,h});if(p){slide().modules=p;syncModulePositions();break;}}}}
 check();
}
