function insertDialog(preferred='text'){if(!drawRect){chooseSpace(preferred,r=>{drawRect=r;insertDialog(preferred);});return;}if(slide().kind!=='body')return toast('请先选择正文页，或点击左侧“＋”新增正文页。',true);const space=drawRect||findSpace(layoutItems(),project.grid,pageBounds(),preferred.startsWith('textbox')?{type:'text',textBox:true}:{});if(!space)return toast('当前页面没有足够的留白，请缩小已有模块或新增一页。',true);drawRect=space;newDialog('insert-dialog','插入模块',`<div class="file-note">插入范围：${Math.round(space.w)} × ${Math.round(space.h)} px；${drawing?'按圈定范围':'自动选择当前可容纳的最大矩形留白'}。</div><label>模块类型<select id="insert-type"><option value="text">分组文字模块</option><option value="textbox-dark">独立文本块 · 深底白字</option><option value="textbox-light">独立文本块 · 白底深字</option><option value="table">表格</option><option value="media">图像 / 视频（可带长图注）</option><option value="timeline">时间轴（年份、事件、照片或视频）</option><option value="shape">几何箭头</option><option value="formula">LaTeX 公式</option></select></label><div class="row"><label>子区域数量<input id="insert-count" type="number" min="1" max="12" value="2"></label><label>文本块样式<select id="insert-style">${STYLES.map(([v,n,t])=>`<option value="${v}">${n}　${t}</option>`).join('')}</select></label></div><p class="hint">子区域先均分，可在“编辑模块”中重新分列或增删。表格、几何图形使用单一区域。</p>`,'插入');$('#insert-type').value=preferred;if(preferred.startsWith('textbox')){$('#insert-count').value='1';$('#insert-count').disabled=true;$('#insert-style').disabled=true;}}
async function themeDialog(){newDialog('theme-dialog','主题与学校标志',`<label>学校 / 机构名称<input id="theme-name" value="${esc(project.theme.name)}"></label><div class="row">${[['primary','主题色 *'],['secondary','第二主题色（可选）'],['accent','装饰色（可选）'],['emphasis','强调色（可选）'],['tint','卡片浅底（可选）'],['ink','正文颜色（可选）']].map(([k,t])=>`<label>${t}<span class="field-line"><input type="color" data-color-for="theme-${k}" value="${project.theme[k]}"><input id="theme-${k}" value="${project.theme[k]}" placeholder="#RRGGBB"></span></label>`).join('')}</div><label>独立校徽<input id="theme-logo" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"></label><label>包含校名的组合标识<input id="theme-wordmark" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"></label><p class="hint">留空保留原标志。标志等比适配，不改色、不拉伸。<a href="https://www.cnblogs.com/cdz-111/articles/22432508" target="_blank" rel="noopener" title="发布于 2026-08-12 22:38">中国高校校徽（LOGO）官方下载资源汇总</a>。可选色留空将由主题色派生。</p>`);}
function pageSettings(){newDialog('page-dialog','页面标题与来源',`<label>标题<textarea id="page-title" rows="2">${esc(slide().title)}</textarea></label><label>章节归属<select id="page-chapter-mode"><option value="auto" ${slide().chapterMode!=='manual'?'selected':''}>自动继承最近过渡页</option><option value="manual" ${slide().chapterMode==='manual'?'selected':''}>自定义章节／无过渡页附录</option></select></label><div class="row"><label>章节号／附录标签<input id="page-section" value="${esc(slide().section)}"></label><label>章节名称<input id="page-group" value="${esc(slide().group)}"></label></div><label>页首句（可选，留空不显示）<textarea id="page-lead" rows="2">${esc(slide().lead)}</textarea></label><label>页尾总结（可选；主题色底、白字、16 pt 加粗）<textarea id="page-summary" rows="2">${esc(slide().summary)}</textarea></label><label>左下角脚注<input id="page-footer" value="${esc(slide().footer??(project.theme.name+' · 科研汇报'))}"></label><label>本页备注（仅演讲者可见）<textarea id="page-notes" rows="5" placeholder="写下讲解要点、过渡提示或补充数据…">${esc(slide().notes||'')}</textarea></label><p class="hint">保存后，点击顶部“页面备注”即自动载入；与备注面板共用同一份内容。</p><label>脚注来源文字<input id="page-source" value="${esc(slide().source)}"></label><label>来源链接（http / https 或 #slide-页面ID）<input id="page-url" value="${esc(slide().sourceUrl)}"></label>`);}
async function mediaDialog(m,i){mediaTarget={id:m.id,i};currentAsset=clone(resolveThemeAsset(m.parts[i].asset,project.theme));const p=m.parts[i];newDialog('media-dialog','图片 / 视频与图注',`<label>上传媒体<input id="media-file" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml,video/mp4,video/webm"></label><div class="crop-preview"><div id="crop-box" class="crop-box"></div></div><div class="row"><label>裁剪比例<select id="media-ratio"><option value="1.7777777777777777">16 : 9</option><option value="1.3333333333333333">4 : 3</option><option value="1">1 : 1</option><option value="original">原始比例（完整显示）</option><option value="custom">自定义宽高比</option></select></label><label>等比放大<input id="media-zoom" type="range" min="1" max="3" step=".05" value="${currentAsset?.zoom||1}"></label><label>水平取景<input id="media-cx" type="range" min="0" max="100" value="${currentAsset?.cx??50}"></label><label>垂直取景<input id="media-cy" type="range" min="0" max="100" value="${currentAsset?.cy??50}"></label></div><div class="row" id="media-custom-fields" hidden><label>比例宽<input id="media-custom-w" type="number" min="0.000001" step="any" value="${currentAsset?.ratioWidth||currentAsset?.ratio||16}"></label><label>比例高<input id="media-custom-h" type="number" min="0.000001" step="any" value="${currentAsset?.ratioHeight||1}"></label></div><label><span><input id="media-caption-show" type="checkbox" ${p.showCaption!==false?'checked':''}> 保留图标题（取消勾选可删除）</span></label><label>图注形式<select id="media-caption-mode"><option value="note">14 pt 图标题 + 12 pt 注释</option><option value="title" ${p.captionMode==='title'?'selected':''}>仅图标题</option></select></label><p class="hint">可输入任意正数宽高比，如 3:2、5:4 或 2.35:1。并排媒体的实际画面严格等高，宽度随比例变化；图注独立排在下方。裁剪不拉伸图像。图注增长时先压缩媒体区域，仍无法容纳时会标红。视频支持 MP4 / WebM，单个文件不超过 25 MB。</p>`);if(currentAsset){const preset=[...$('#media-ratio').options].find(o=>Number(o.value)===currentAsset.ratio);$('#media-ratio').value=currentAsset.ratioMode==='original'||currentAsset.fit==='contain'?'original':currentAsset.ratioMode==='custom'||!preset?'custom':preset.value;}if(m.type==='timeline'){$('#media-ratio').closest('label').hidden=true;$('#media-caption-show').closest('label').hidden=true;$('#media-caption-mode').closest('label').hidden=true;$('#media-dialog .hint').textContent='时间轴使用统一尺寸的媒体框，随阶段数量自动调整。可替换照片或MP4/WebM视频，并调整缩放及取景；年份与事件请在画布中编辑。';}cropPreview();}
function mediaRatio(){
 const mode=$('#media-ratio').value;
 if(mode==='original')return currentAsset?.naturalRatio||16/9;
 if(mode!=='custom')return Number(mode);
 const width=Number($('#media-custom-w').value),height=Number($('#media-custom-h').value),ratio=width/height;
 if(!Number.isFinite(width)||!Number.isFinite(height)||width<=0||height<=0||!Number.isFinite(ratio)||ratio<=0)throw Error('自定义比例的宽和高必须是大于 0 的有限数值。');
 return ratio;
}
function cropPreview(){
 const box=$('#crop-box');if(!box)return;$('#media-custom-fields').hidden=$('#media-ratio').value!=='custom';
 let r;try{r=mediaRatio();}catch(error){box.innerHTML='<p class="hint">'+esc(error.message)+'</p>';return;}
 if(!currentAsset){box.innerHTML='<p class="hint">选择媒体后预览取景</p>';return;}
 const w=Math.min(580,220*r),h=w/r;box.style.width=w+'px';box.style.height=h+'px';const tag=currentAsset.kind==='video'?'video':'img';
 box.innerHTML=`<${tag} src="${currentAsset.src}" ${tag==='video'?'muted controls':''} style="object-fit:${$('#media-ratio').value==='original'?'contain':'cover'};object-position:${$('#media-cx').value}% ${$('#media-cy').value}%;transform:scale(${$('#media-zoom').value});transform-origin:${$('#media-cx').value}% ${$('#media-cy').value}%">`;
}
