function openFormulaEditor(target,latex){formulaTarget=target;const m=slide().modules.find(m=>m.id===target.id),owner=m&&tableOwner(m,target.part||0),useTheme=target.cell?(owner.cellMathColors?.[target.r+','+target.c+','+target.i]??m.mathUseThemeColor):m?.parts[target.i]?.useThemeColor??m?.mathUseThemeColor??(target.symbol&&slide().symbolUseThemeColor!==false);newDialog('formula-dialog',target.symbol?'编辑符号（LaTeX）':'编辑公式',`<label class="formula-color-choice"><input id="formula-use-theme" type="checkbox" ${useTheme?'checked':''}> 使用主题色（取消为纯黑）</label><label for="formula-latex">LaTeX 源码</label><textarea id="formula-latex" rows="6" spellcheck="false" aria-describedby="formula-help formula-validation">${esc(latex)}</textarea><div class="formula-editor-actions"><button type="button" data-action="copy-formula">复制 LaTeX</button><span id="formula-help" class="hint">可直接复制或修改源码，无需外层 $。</span></div><p id="formula-validation" class="formula-validation" role="alert" hidden></p><div id="formula-preview" class="formula-editor-preview" aria-label="公式预览"></div><p class="hint">修改后点击“确定”。语法错误时保留输入，请修正后重新确认；取消则保留原公式。</p>`,'确定');previewFormula();}
function previewFormula(focus=false){const box=$('#formula-preview'),input=$('#formula-latex'),message=$('#formula-validation');if(!box||!input)return false;try{checkFormula(input.value);box.innerHTML=formulaHTML(input.value);box.style.color=$('#formula-use-theme')?.checked?project.theme.primary:'#000000';input.setAttribute('aria-invalid','false');if(message){message.hidden=true;message.textContent='';}return true;}catch(error){box.replaceChildren();input.setAttribute('aria-invalid','true');if(message){message.hidden=false;message.textContent=(input.value.trim()?'LaTeX 语法有误，请修改后重新确认。':'请填写 LaTeX 公式后重新确认。')+'\n'+error.message;}if(focus)input.focus();return false;}}
